create extension if not exists pgcrypto;
create type public.member_status as enum ('pending','active','suspended','left');
create type public.contribution_status as enum ('pending','confirmed','rejected');
create type public.group_status as enum ('forming','active','completed','cancelled');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, phone text unique, role text not null default 'member' check (role in ('member','admin')), created_at timestamptz not null default now());
create table public.packages (id uuid primary key default gen_random_uuid(), name text not null, daily_amount integer not null check (daily_amount > 0), active boolean not null default true, created_at timestamptz not null default now());
create table public.savings_groups (id uuid primary key default gen_random_uuid(), name text not null, package_id uuid not null references public.packages(id), capacity integer not null check (capacity > 1), status public.group_status not null default 'forming', starts_on date, created_at timestamptz not null default now());
create table public.group_members (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.savings_groups(id), user_id uuid not null references public.profiles(id), status public.member_status not null default 'pending', joined_at timestamptz not null default now(), unique(group_id,user_id));
create table public.contributions (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.savings_groups(id), user_id uuid not null references public.profiles(id), amount integer not null check (amount > 0), due_on date not null, status public.contribution_status not null default 'pending', proof_path text, submitted_at timestamptz, reviewed_by uuid references public.profiles(id), reviewed_at timestamptz, review_note text, created_at timestamptz not null default now());
create table public.payout_schedule (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.savings_groups(id), user_id uuid not null references public.profiles(id), sequence_no integer not null check (sequence_no > 0), scheduled_on date not null, status text not null default 'scheduled' check (status in ('scheduled','paid','held','cancelled')), unique(group_id,sequence_no), unique(group_id,user_id));
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index contributions_user_group_due_idx on public.contributions(user_id,group_id,due_on);
create index group_members_user_idx on public.group_members(user_id,status);
create index payout_schedule_group_date_idx on public.payout_schedule(group_id,scheduled_on);
alter table public.profiles enable row level security;
alter table public.packages enable row level security;
alter table public.savings_groups enable row level security;
alter table public.group_members enable row level security;
alter table public.contributions enable row level security;
alter table public.payout_schedule enable row level security;
alter table public.audit_logs enable row level security;
create policy "Members can read own profile" on public.profiles for select to authenticated using (id = auth.uid());
create policy "Members can update own profile" on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy "Authenticated users can view active packages" on public.packages for select to authenticated using (active = true);
create policy "Authenticated users can view forming or active groups" on public.savings_groups for select to authenticated using (status in ('forming','active'));
create policy "Members can view own memberships" on public.group_members for select to authenticated using (user_id = auth.uid());
create policy "Members can request membership" on public.group_members for insert to authenticated with check (user_id = auth.uid() and status = 'pending');
create policy "Members can view own contributions" on public.contributions for select to authenticated using (user_id = auth.uid());
create policy "Members can submit own pending contributions" on public.contributions for insert to authenticated with check (user_id = auth.uid() and status = 'pending' and reviewed_by is null and reviewed_at is null);
create policy "Members can view own payout schedule" on public.payout_schedule for select to authenticated using (user_id = auth.uid());
-- Add secure server-verified admin policies and private Storage policies before production.
